import {useCallback,useEffect,useState} from 'react';
import {Check,Copy,Link2,RefreshCw,ShieldCheck,Smartphone,X} from 'lucide-react';
import {createFiteatsyConnectionInvitation,listFiteatsyConnections,revokeFiteatsyConnection,revokeFiteatsyConnectionInvitation} from '../../lib/practiceOperationsApi';

const SCOPES=['PROFILE','HEALTH_SUMMARY','MEASUREMENTS','BIOMARKERS','DIET_PLANS','APPOINTMENTS'];
const label=value=>value.replaceAll('_',' ').toLowerCase().replace(/^./,c=>c.toUpperCase());

export function ExternalFiteatsyConnections({clients=[]}){
  const [state,setState]=useState({loading:true,data:null,error:''});
  const [clientId,setClientId]=useState('');
  const [busy,setBusy]=useState(false);
  const [secret,setSecret]=useState(null);
  const [copied,setCopied]=useState(false);
  const load=useCallback(async()=>{setState(s=>({...s,loading:true,error:''}));try{setState({loading:false,data:await listFiteatsyConnections(),error:''});}catch(error){setState({loading:false,data:null,error:error.message||'Connection workspace could not be loaded.'});}},[]);
  useEffect(()=>{load();},[load]);
  const create=async()=>{setBusy(true);try{setSecret(await createFiteatsyConnectionInvitation({client_id:clientId||null,expires_in_hours:72,scopes:SCOPES}));await load();}catch(error){setState(s=>({...s,error:error.message}));}finally{setBusy(false);}};
  const act=async fn=>{setBusy(true);try{await fn();setSecret(null);await load();}catch(error){setState(s=>({...s,error:error.message}));}finally{setBusy(false);}};
  const copy=async()=>{await navigator.clipboard.writeText(secret.connection_pin);setCopied(true);setTimeout(()=>setCopied(false),1800);};
  const share=()=>{const text=`Use this one-time Zestiva Connection PIN: ${secret.connection_pin}. It expires ${new Date(secret.expires_at).toLocaleString()}. Open Fiteatsy and choose Connect consultant.`;window.open(`https://wa.me/?text=${encodeURIComponent(text)}`,'_blank','noopener,noreferrer');};
  const disabled=state.error.toLowerCase().includes('not enabled');
  return <section className="overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-sm"><div className="bg-gradient-to-br from-slate-950 via-blue-950 to-cyan-900 p-5 text-white sm:p-7"><p className="text-xs font-bold uppercase tracking-[.18em] text-cyan-300">Connected care</p><h2 className="mt-2 text-2xl font-bold">Connect a Fiteatsy client</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-blue-100">Generate a short-lived PIN. The client redeems it in their authenticated Fiteatsy app and chooses what to share.</p><span className="mt-4 inline-flex items-center gap-2 rounded-full border border-white/20 bg-white/10 px-3 py-2 text-xs font-semibold"><ShieldCheck size={16}/>Consent controlled</span></div><div className="grid gap-6 p-5 sm:p-7 xl:grid-cols-2"><div><h3 className="font-bold">New connection</h3><label className="mt-4 block text-sm font-semibold">Link to a client (optional)<select value={clientId} onChange={e=>setClientId(e.target.value)} className="mt-2 min-h-12 w-full rounded-xl border border-slate-200 bg-white px-3"><option value="">No client selected</option>{clients.map(client=><option key={client.id} value={client.id}>{client.displayName}</option>)}</select></label><button disabled={busy||disabled} onClick={create} className="mt-4 inline-flex min-h-12 items-center gap-2 rounded-xl bg-blue-700 px-5 font-bold text-white disabled:opacity-40"><Link2 size={18}/>{busy?'Generating…':'Generate Connection PIN'}</button><p className="mt-3 text-xs leading-5 text-slate-500">PINs expire after 72 hours, are stored only as secure verifiers, and can be revoked.</p>{secret&&<div role="status" className="mt-5 rounded-2xl border border-emerald-200 bg-emerald-50 p-4"><p className="text-xs font-bold uppercase tracking-widest text-emerald-800">Shown once</p><p className="mt-2 font-mono text-3xl font-bold tracking-[.18em]">{secret.connection_pin}</p><p className="mt-2 text-xs text-slate-600">Expires {new Date(secret.expires_at).toLocaleString()}</p><div className="mt-4 flex flex-wrap gap-2"><button onClick={copy} className="inline-flex min-h-11 items-center gap-2 rounded-xl border bg-white px-4 text-sm font-bold">{copied?<Check size={16}/>:<Copy size={16}/>} {copied?'Copied':'Copy PIN'}</button><button onClick={share} className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-emerald-700 px-4 text-sm font-bold text-white"><Smartphone size={16}/>Share via WhatsApp</button></div></div>}</div><div><div className="flex items-center justify-between"><h3 className="font-bold">Connections</h3><button onClick={load} aria-label="Refresh connections" className="grid h-11 w-11 place-items-center rounded-xl border"><RefreshCw size={17}/></button></div>{state.loading?<p className="mt-5 text-sm text-slate-500">Loading connections…</p>:state.error?<div className="mt-5 rounded-2xl border border-red-200 bg-red-50 p-4 text-sm text-red-800"><p className="font-bold">{disabled?'Connections are not enabled yet':'Connections unavailable'}</p><p className="mt-1">{state.error}</p></div>:<div className="mt-4 space-y-3">{(state.data?.connections||[]).map(item=><article key={item.id} className="rounded-2xl border p-4"><p className="font-bold">Active Fiteatsy connection</p><p className="mt-1 text-xs text-slate-500">{(item.consented_scopes||[]).map(label).join(' · ')}</p><button disabled={busy} onClick={()=>act(()=>revokeFiteatsyConnection(item.id))} className="mt-4 inline-flex min-h-10 items-center gap-2 rounded-xl border border-red-200 px-3 text-xs font-bold text-red-700"><X size={15}/>Disconnect</button></article>)}{(state.data?.invitations||[]).filter(item=>item.status==='PENDING').map(item=><article key={item.id} className="rounded-2xl border border-amber-200 bg-amber-50 p-4"><p className="font-bold">Pending PIN · ends in {item.pin_hint}</p><p className="mt-1 text-xs">Expires {new Date(item.expires_at).toLocaleString()}</p><button disabled={busy} onClick={()=>act(()=>revokeFiteatsyConnectionInvitation(item.id))} className="mt-3 min-h-10 rounded-xl border bg-white px-3 text-xs font-bold">Revoke PIN</button></article>)}{!(state.data?.connections||[]).length&&!(state.data?.invitations||[]).some(item=>item.status==='PENDING')&&<p className="rounded-2xl border border-dashed p-6 text-center text-sm text-slate-500">No Fiteatsy connections yet.</p>}</div>}</div></div></section>;
}
